set -euo pipefail
R=/dataset/shaoshitong/search-r1-rl/cosearch
base64 -d > "$R/tools/retrieval_compare.py" <<'PYCODE'

PYCODE
export PATH="$R/env/bin:/root/.local/bin:$PATH" SEARCH_R1_BASE="$R"
# The bootstrap's final GPU check is deferred to the proper allocation.
python - <<'PYCODE'
import hashlib,json,urllib.request
from pathlib import Path
r=Path('/dataset/shaoshitong/search-r1-rl/cosearch')
name='faiss_gpu_cu12-1.8.0.2-cp310-cp310-manylinux_2_28_x86_64.whl'
sha='7ea5e6aa82897fd0c1af3b1decc9c8659a4398fed42de1d7746715b64bbf9bf9'
p=r/'wheelhouse'/name
if not p.exists():
    d=json.load(urllib.request.urlopen('https://pypi.org/pypi/faiss-gpu-cu12/1.8.0.2/json',timeout=15))
    url=next(f['url'] for f in d['urls'] if f['filename']==name)
    partial=p.with_suffix('.partial')
    urllib.request.urlretrieve(url,partial)
    assert hashlib.sha256(partial.read_bytes()).hexdigest()==sha
    partial.replace(p)
assert hashlib.sha256(p.read_bytes()).hexdigest()==sha
print('PINNED_GPU_FAISS_WHEEL_SHA_OK',flush=True)
PYCODE
uv pip install --python "$R/env/bin/python" --target "$R/retriever-gpu-lib" --no-deps "$R/wheelhouse/faiss_gpu_cu12-1.8.0.2-cp310-cp310-manylinux_2_28_x86_64.whl"
